17	import { emit, subscribe, subscriberCount } from "@/lib/event-bus";
18	import { PermissionDeniedError } from "@/lib/permissions";
19	import { TenantScopeError } from "@/lib/tenant";
20	import * as activityRepo from "@/server/repositories/activity-repository";
21	import {
22	  exportActivity,
23	  groupByDay,
