26	} from "@/server/services/activity-service";
27	import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
28	import type { Tenant } from "../server/_support/fixtures";
29	import type { ActivityEvent } from "@/types/activity";
30	import type { CommentId, IssueId } from "@/types/common";
31	import type { Unsubscribe } from "@/types/event";
32	
33	let cleanup: () => void;
34	let tenant: Tenant;
35	let detach: Unsubscribe;
36	
37	beforeAll(async () => {
38	  cleanup = await useTemporaryDatabase();
39	  tenant = await createTenant("activity", "growth");
40	  detach = registerActivityListeners();
41	});
42	
43	afterAll(() => {
44	  detach();
45	  cleanup();
46	});
47	
48	afterEach(() => {
49	  vi.mocked(activityRepo.insertActivity).mockClear();
50	});
51	
52	describe("services/activity-service", () => {
53	  // subscribe() is registered for each ActivityAction-shaped event type.
54	  it("subscribes to every event that maps to an ActivityAction", () => {
55	    const before = subscriberCount("project.created");
56	    const off = registerActivityListeners();
57	
58	    // registerActivityListeners() is idempotent per call — each call attaches
59	    // its own listener set, so calling it a second time adds one more.
60	    expect(subscriberCount("project.created")).toBe(before + 1);
61	    expect(subscriberCount("issue.created")).toBeGreaterThanOrEqual(1);
62	    expect(subscriberCount("member.role_changed")).toBeGreaterThanOrEqual(1);
63	    expect(subscriberCount("billing.plan_changed")).toBeGreaterThanOrEqual(1);
64	
65	    off();
66	    expect(subscriberCount("project.created")).toBe(before);
67	  });
68	
69	  // One emit produces exactly one activity row, with the actor and subject.
70	  it("records one audit row per emitted event", async () => {
71	    await emit("project.created", {
72	      orgId: tenant.org.id,
73	      actorId: tenant.userIds.member,
74	      occurredAt: tenant.org.createdAt,
75	      projectId: tenant.project.id,
76	      name: "Audited project",
77	      slug: "audited-project",
78	    });
79	
80	    const page = await listActivity(tenant.actors.member, {
81	      orgId: tenant.org.id,
82	      action: ["project.created"],
83	      limit: 25,
84	      cursor: null,
85	    });
86	
87	    expect(page.items).toHaveLength(1);
88	    expect(page.items[0]).toMatchObject({
89	      orgId: tenant.org.id,
