 * Batched read of known issues, returned in the order the ids were given.
 * Archived rows are included: a replayed import must return what it created.
 */
export async function findIssuesByIds(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<readonly Issue[]> {
  if (issueIds.length === 0) return [];

  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), inArray(issues.id, [...issueIds])),
    )
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.id as IssueId),
  );
  const byId = new Map(
    rows.map((row) => [
      row.id,
      toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
    ]),
  );

  return issueIds.flatMap((id) => {
    const issue = byId.get(id);
    return issue ? [issue] : [];
  });
}

