 *
 * Must call (do not reimplement): newId, orgPredicate, toIssue
 */
import { and, eq, inArray, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, issueImports, issueLabels, issues, labels } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { brandId, toIssue } from "./_mappers";
import { orgPredicate } from "./base-repository";
import type {
  IsoTimestamp,
  IssueId,
  LabelId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { Issue, IssuePriority, IssueStatus } from "@/types/issue";

export interface IssueImportRecord {
  readonly importKey: string;
  readonly projectId: ProjectId;
  readonly issueIds: readonly IssueId[];
}

/** A batch row once the service has resolved its assignee and de-duplicated its labels. */
export interface ImportRowPlan {
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly assigneeId: UserId | null;
  readonly dueAt: IsoTimestamp | null;
  readonly labelNames: readonly string[];
}

/** The ledger entry for an earlier upload with this key in this workspace, if any. */
export async function findIssueImport(
  orgId: OrgId,
  importKey: string,
): Promise<IssueImportRecord | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();
  if (!row) return null;

  return {
    importKey: row.importKey,
    projectId: brandId<ProjectId>(row.projectId),
    issueIds: (JSON.parse(row.issueIds) as string[]).map((id) =>
      brandId<IssueId>(id),
    ),
  };
}

/**
 * Writes a batch or nothing. Inside one transaction: labels that do not exist
 * yet are created, the issues are inserted in file order after the project's
 * highest number, their label links follow, and the ledger entry is recorded.
 * Any failure, including a concurrent reuse of the key, rolls all of it back.
 */
export async function insertIssueImport(input: {
  readonly orgId: OrgId;
  readonly projectId: ProjectId;
  readonly importKey: string;
  readonly importedBy: UserId;
  readonly rows: readonly ImportRowPlan[];
}): Promise<readonly Issue[]> {
  const stamp = toIsoTimestamp(new Date());

  return getDb().transaction((tx) => {
    const top = tx
      .select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, input.orgId),
          eq(issues.projectId, input.projectId),
        ),
      )
      .get();
    const firstNumber = (top?.value ?? 0) + 1;

    const names = [...new Set(input.rows.flatMap((row) => row.labelNames))];
    const labelIdByName = new Map<string, LabelId>();

    if (names.length > 0) {
      const existing = tx
        .select({ id: labels.id, name: labels.name })
        .from(labels)
        .where(
          and(
            orgPredicate(labels.orgId, input.orgId),
            inArray(labels.name, names),
          ),
        )
        .all();
      for (const label of existing) {
        labelIdByName.set(label.name, brandId<LabelId>(label.id));
      }
    }

    for (const name of names) {
      if (labelIdByName.has(name)) continue;

      // Colour and description are left to the column defaults: the default
      // colour and no description, as for a label created with no options.
      const labelId = brandId<LabelId>(newId());
      tx.insert(labels)
        .values({
          id: labelId,
          orgId: input.orgId,
          name,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();
      labelIdByName.set(name, labelId);
    }

    const created = input.rows.map((row, index) => {
      const issueId = brandId<IssueId>(newId());
      const issueRow = tx
        .insert(issues)
        .values({
          id: issueId,
          orgId: input.orgId,
          projectId: input.projectId,
          number: firstNumber + index,
          title: row.title,
          description: row.description,
          status: row.status,
          priority: row.priority,
          authorId: input.importedBy,
          assigneeId: row.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: row.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning()
        .get();

      const labelIds = row.labelNames.flatMap((name) => {
        const labelId = labelIdByName.get(name);
        return labelId === undefined ? [] : [labelId];
      });
      if (labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            labelIds.map((labelId) => ({
              orgId: input.orgId,
              issueId,
              labelId,
            })),
          )
          .run();
      }

      return toIssue(issueRow, labelIds);
    });

    tx.insert(issueImports)
      .values({
        id: newId(),
        orgId: input.orgId,
        importKey: input.importKey,
        projectId: input.projectId,
        importedBy: input.importedBy,
        issueIds: JSON.stringify(created.map((issue) => issue.id)),
        createdAt: stamp,
      })
      .run();

    return created;
  });
}

