/**
 * Bulk import of an uploaded file into one project. The access gates are the
 * ones a single create runs. A key already imported in this workspace replays
 * its first result and writes nothing. Otherwise the batch must clear the plan
 * quota and the issue-creation rate allowance (one unit per row) before anything
 * is written. The batch then commits all or nothing and is announced once, as
 * `issues.imported`, which carries everything the per-issue events would have.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const prior = await issueImportRepo.findIssueImport(
    input.orgId,
    input.importKey,
  );
  if (prior !== null) {
    return {
      importKey: prior.importKey,
      projectId: prior.projectId,
      issues: await issueRepo.findIssuesByIds(input.orgId, prior.issueIds),
      replayed: true,
    };
  }

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  assertProjectQuotaRoom(org, project, used, input.rows.length);

  // The limiter sizes buckets by plan, so record this org's plan before spending.
  setOrgPlan(input.orgId, org.plan);
  const verdict = await consumeRateLimit(
    input.orgId,
    ISSUE_CREATE_BUCKET,
    input.rows.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue creation rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const assigneeEmails = [
    ...new Set(
      input.rows.flatMap((row) =>
        row.assigneeEmail === null ? [] : [row.assigneeEmail.toLowerCase()],
      ),
    ),
  ];
  const assigneeIds = await memberRepo.findActiveUserIdsByEmail(
    input.orgId,
    assigneeEmails,
  );

  const issues = await issueImportRepo.insertIssueImport({
    orgId: input.orgId,
    projectId: project.id,
    importKey: input.importKey,
    importedBy: actor.userId,
    rows: input.rows.map((row) => ({
      title: row.title,
      description: row.description,
      status: row.status,
      priority: row.priority,
      assigneeId:
        row.assigneeEmail === null
          ? null
          : (assigneeIds.get(row.assigneeEmail.toLowerCase()) ?? null),
      dueAt: row.dueAt,
      labelNames: [...new Set(row.labels)],
    })),
  });

  await emit("issues.imported", {
    ...actorEnvelope(actor),
    projectId: project.id,
    importKey: input.importKey,
    issueIds: issues.map((issue) => issue.id),
  });

  return {
    importKey: input.importKey,
    projectId: project.id,
    issues,
    replayed: false,
  };
}

/**
 * The per-project issue quota, shared by a single create and a batch import so
 * both refuse with the same error. `used` counts live issues.
 */
function assertProjectQuotaRoom(
  org: Organization,
  project: Project,
  used: number,
  requested: number,
): void {
  if (wouldExceedLimit(org.plan, "issuesPerProject", used, requested)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }
}

