/**
 * Bulk issue import: the access gates, all-or-nothing writes, replays, and the
 * single `issues.imported` announcement that search, usage and the audit log
 * react to. Handlers are attached the way the server attaches them at start-up.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { getDb } from "@/server/db";
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import * as activityService from "@/server/services/activity-service";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import { NotFoundError } from "@/server/services/_support";
import * as issueService from "@/server/services/issue-service";
import * as notificationService from "@/server/services/notification-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { registerEventHandlers, unregisterEventHandlers } from "@/server/services/event-registry";
import * as webhookService from "@/server/services/webhook-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { ImportIssueRowInput, ImportIssuesInput } from "@/schemas/issue-import";
import type { ProjectId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

/** Collects every payload delivered for one event type during a test. */
function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

/** A batch row with every schema default written out, so each test states only what it cares about. */
function row(
  title: string,
  overrides: Partial<ImportIssueRowInput> = {},
): ImportIssueRowInput {
  return {
    title,
    description: null,
    status: "backlog",
    priority: "none",
    assigneeEmail: null,
    labels: [],
    dueAt: null,
    ...overrides,
  };
}

function batch(
  tenant: Tenant,
  importKey: string,
  rows: readonly ImportIssueRowInput[],
  projectId: ProjectId = tenant.project.id,
): ImportIssuesInput {
  return { orgId: tenant.org.id, projectId, importKey, rows: [...rows] };
}

function rowCountFor(orgId: string): number {
  const result = getDb()
    .$client.prepare("SELECT COUNT(*) AS n FROM webhook_deliveries WHERE org_id = ?")
    .get(orgId) as { n: number };
  return result.n;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerEventHandlers();
});

afterAll(() => {
  while (detachers.length > 0) detachers.pop()?.();
  unregisterEventHandlers();
  cleanup();
});

describe("services/issue-service — importIssues: access", () => {
  it("refuses an actor without issue:create and leaves the key unused", async () => {
    const tenant = await createTenant("imp-viewer");
    const rows = [row("Viewer cannot import")];

    await expect(
      issueService.importIssues(tenant.actors.viewer, batch(tenant, "viewer-key-01", rows)),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const retry = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "viewer-key-01", rows),
    );
    expect(retry.replayed).toBe(false);
    expect(retry.issues).toHaveLength(1);
  });

  it("refuses an org outside the actor's workspace with TenantScopeError", async () => {
    const home = await createTenant("imp-home");
    const elsewhere = await createTenant("imp-elsewhere");

    await expect(
      issueService.importIssues(
        elsewhere.actors.owner,
        batch(home, "scope-key-0001", [row("Not yours")]),
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("treats a project of another workspace as not found", async () => {
    const home = await createTenant("imp-notfound");
    const other = await createTenant("imp-notfound-other");

    await expect(
      issueService.importIssues(
        home.actors.member,
        batch(home, "notfound-key-01", [row("Wrong project")], other.project.id),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses an archived project with AlreadyArchivedError", async () => {
    const tenant = await createTenant("imp-archived");
    const project = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Retired",
      slug: "retired",
      key: "RET",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: project.id,
      archiveIssues: true,
    });

    await expect(
      issueService.importIssues(
        tenant.actors.member,
        batch(tenant, "archived-key-01", [row("Too late")], project.id),
      ),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });
});

describe("services/issue-service — importIssues: writes", () => {
  it("creates every row in file order, numbered after the project's highest number", async () => {
    const tenant = await createTenant("imp-order");
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Seed issue" }),
    );

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "order-key-0001", [
        row("First imported"),
        row("Second imported"),
        row("Third imported"),
      ]),
    );

    expect(result.replayed).toBe(false);
    expect(result.projectId).toBe(tenant.project.id);
    expect(result.issues.map((issue) => issue.title)).toEqual([
      "First imported",
      "Second imported",
      "Third imported",
    ]);
    expect(result.issues.map((issue) => issue.number)).toEqual([2, 3, 4]);
    for (const issue of result.issues) {
      expect(issue.authorId).toBe(tenant.userIds.member);
      expect(issue.parentId).toBeNull();
      expect(issue.estimate).toBeNull();
    }

    const next = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "After the import" }),
    );
    expect(next.number).toBe(5);
  });

  it("keeps title, description, status, priority and due date exactly as given", async () => {
    const tenant = await createTenant("imp-fields");

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "fields-key-0001", [
        row("Fielded row", {
          description: "The body",
          status: "in_progress",
          priority: "high",
          dueAt: "2026-06-01T00:00:00.000Z",
        }),
      ]),
    );

    expect(result.issues[0]).toMatchObject({
      title: "Fielded row",
      description: "The body",
      status: "in_progress",
      priority: "high",
      dueAt: "2026-06-01T00:00:00.000Z",
    });
  });

  it("publishes one issues.imported for the batch and no issue.created", async () => {
    const tenant = await createTenant("imp-events");
    const imported = capture("issues.imported");
    const created = capture("issue.created");

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "events-key-0001", [row("Event one"), row("Event two")]),
    );

    expect(created).toHaveLength(0);
    expect(imported).toHaveLength(1);
    expect(imported[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      projectId: tenant.project.id,
      importKey: "events-key-0001",
      issueIds: result.issues.map((issue) => issue.id),
    });
  });

  it("writes nothing when a row is refused by the quota, and leaves the key unused", async () => {
    const tenant = await createTenant("imp-quota", "free");
    // The free plan allows 100 issues per project; seed 98 directly.
    for (let number = 1; number <= 98; number += 1) {
      await issueRepo.insertIssue(
        issueInput(tenant.org.id, tenant.project.id, { title: `Seed ${number}` }),
        tenant.userIds.member,
        number,
      );
    }

    await expect(
      issueService.importIssues(
        tenant.actors.member,
        batch(tenant, "quota-key-0001", [row("One"), row("Two"), row("Three")]),
      ),
    ).rejects.toThrow(/allows no more issues/);
    await expect(issueRepo.countIssues(tenant.org.id, tenant.project.id)).resolves.toBe(98);

    const fits = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "quota-key-0001", [row("One"), row("Two")]),
    );
    expect(fits.replayed).toBe(false);
    await expect(issueRepo.countIssues(tenant.org.id, tenant.project.id)).resolves.toBe(100);
  });

  it("refuses a batch the issue-creation allowance does not cover, and leaves the key unused", async () => {
    const tenant = await createTenant("imp-rate", "free");
    // A free workspace's issue-creation bucket holds 60 units; 61 rows overdraw it.
    const tooMany = Array.from({ length: 61 }, (_, index) => row(`Rate row ${index + 1}`));

    await expect(
      issueService.importIssues(
        tenant.actors.member,
        batch(tenant, "rate-key-00001", tooMany),
      ),
    ).rejects.toThrow(/rate limit/i);
    await expect(issueRepo.countIssues(tenant.org.id, tenant.project.id)).resolves.toBe(0);

    const retry = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "rate-key-00001", [row("Retry row")]),
    );
    expect(retry.replayed).toBe(false);
  });

  it("sizes the allowance by the workspace's plan", async () => {
    const tenant = await createTenant("imp-rate-growth", "growth");
    const rows = Array.from({ length: 61 }, (_, index) => row(`Growth row ${index + 1}`));

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "growth-key-00001", rows),
    );
    expect(result.issues).toHaveLength(61);
  });
});

describe("services/issue-service — importIssues: replays", () => {
  it("returns the first result for a reused key, in the same order, and writes and publishes nothing", async () => {
    const tenant = await createTenant("imp-replay");
    const first = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "replay-key-0001", [row("Original A"), row("Original B")]),
    );

    const imported = capture("issues.imported");
    const created = capture("issue.created");
    const replay = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "replay-key-0001", [row("Changed C")]),
    );

    expect(replay.replayed).toBe(true);
    expect(replay.issues.map((issue) => issue.id)).toEqual(
      first.issues.map((issue) => issue.id),
    );
    expect(replay.issues.map((issue) => issue.title)).toEqual(["Original A", "Original B"]);
    expect(imported).toHaveLength(0);
    expect(created).toHaveLength(0);
    await expect(issueRepo.countIssues(tenant.org.id, tenant.project.id)).resolves.toBe(2);
  });

  it("treats the same rows under a different key as a new import", async () => {
    const tenant = await createTenant("imp-newkey");
    const rows = [row("Same rows")];

    const first = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "newkey-first-01", rows),
    );
    const second = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "newkey-second-1", rows),
    );

    expect(second.replayed).toBe(false);
    expect(second.issues[0]?.id).not.toBe(first.issues[0]?.id);
  });

  it("scopes keys to the workspace", async () => {
    const home = await createTenant("imp-keyhome");
    const away = await createTenant("imp-keyaway");

    await issueService.importIssues(
      home.actors.member,
      batch(home, "shared-key-0001", [row("Home row")]),
    );
    const sameKeyElsewhere = await issueService.importIssues(
      away.actors.member,
      batch(away, "shared-key-0001", [row("Away row")]),
    );

    expect(sameKeyElsewhere.replayed).toBe(false);
    expect(sameKeyElsewhere.issues[0]?.title).toBe("Away row");
  });
});

describe("services/issue-service — importIssues: assignees and labels", () => {
  it("matches assignees by email without case, and leaves anything else unassigned", async () => {
    const tenant = await createTenant("imp-assign");
    await userRepo.insertUser({
      email: "outsider@imp-assign.test",
      name: "Outsider",
      passwordHash: "seed",
    });
    const viewerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (viewerMember === null) throw new Error("viewer should be a member");
    await memberRepo.archiveMember(tenant.org.id, viewerMember.id);

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "assign-key-0001", [
        row("Case folded", { assigneeEmail: "ADMIN@imp-assign.test" }),
        row("Not a member", { assigneeEmail: "outsider@imp-assign.test" }),
        row("Removed member", { assigneeEmail: "viewer@imp-assign.test" }),
        row("Unknown address", { assigneeEmail: "nobody@imp-assign.test" }),
      ]),
    );

    expect(result.issues.map((issue) => issue.assigneeId)).toEqual([
      tenant.userIds.admin,
      null,
      null,
      null,
    ]);
  });

  it("matches labels exactly, creates each missing one once, and ignores other workspaces' labels", async () => {
    const tenant = await createTenant("imp-labels");
    const other = await createTenant("imp-labels-other");
    await labelRepo.insertLabel({
      orgId: tenant.org.id,
      name: "Bug",
      color: "#ff0000",
      description: null,
    });
    await labelRepo.insertLabel({
      orgId: other.org.id,
      name: "Epic",
      color: "#00ff00",
      description: null,
    });

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "labels-key-0001", [
        row("Labelled once", { labels: ["Bug", "bug", "Bug"] }),
        row("Labelled again", { labels: ["bug", "Epic"] }),
      ]),
    );

    const labels = await labelRepo.listLabels(tenant.org.id);
    const byName = new Map(labels.map((label) => [label.name, label]));
    expect(labels.map((label) => label.name).sort()).toEqual(["Bug", "Epic", "bug"]);
    expect(byName.get("bug")).toMatchObject({ color: "#94a3b8", description: null });
    expect(byName.get("Epic")?.id).not.toBe(
      (await labelRepo.listLabels(other.org.id)).find((label) => label.name === "Epic")?.id,
    );

    const [first, second] = result.issues;
    expect(first?.labelIds).toEqual([byName.get("Bug")?.id, byName.get("bug")?.id]);
    expect(second?.labelIds).toEqual([byName.get("bug")?.id, byName.get("Epic")?.id]);
  });
});

describe("services/issue-service — importIssues: downstream effects", () => {
  it("is searchable, counts on the usage meter, and is audited once", async () => {
    const tenant = await createTenant("imp-downstream", "growth");
    const usageBefore = (await usageRepo.getUsage(tenant.org.id)).issuesUsed;

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "downstream-key-01", [
        row("Lighthouse alpha"),
        row("Lighthouse beta"),
        row("Lighthouse gamma"),
      ]),
    );

    const hits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Lighthouse",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(hits.total).toBe(3);

    const usageAfter = (await usageRepo.getUsage(tenant.org.id)).issuesUsed;
    expect(usageAfter).toBe(usageBefore + 3);
    const recounted = await usageRepo.recomputeUsage(tenant.org.id);
    expect(recounted.issuesUsed).toBe(usageAfter);

    const audit = await activityService.listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      action: ["issues.imported"],
      limit: 25,
      cursor: null,
    });
    expect(audit.items).toHaveLength(1);
    expect(audit.items[0]).toMatchObject({
      action: "issues.imported",
      actorId: tenant.userIds.member,
      subjectKind: "project",
      subjectId: tenant.project.id,
      projectId: tenant.project.id,
      metadata: { count: 3, importKey: "downstream-key-01" },
    });
    expect(result.issues).toHaveLength(3);

    const perIssue = await activityService.listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      action: ["issue.created"],
      limit: 25,
      cursor: null,
    });
    expect(perIssue.total).toBe(0);
  });

  it("notifies nobody and queues no webhook delivery for the imported issues", async () => {
    const tenant = await createTenant("imp-quiet", "growth");
    await webhookService.createWebhook(tenant.actors.owner, {
      orgId: tenant.org.id,
      url: "https://hooks.example.test/taskflow",
      eventTypes: ["issue.created", "issue.status_changed"],
    });
    const notificationsBefore = await notificationService.listNotifications(
      tenant.actors.admin,
      { orgId: tenant.org.id, recipientId: tenant.userIds.admin, unreadOnly: false, limit: 25, cursor: null },
    );

    await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "quiet-key-000001", [row("Quiet row", { assigneeEmail: "admin@imp-quiet.test" })]),
    );

    const notificationsAfter = await notificationService.listNotifications(
      tenant.actors.admin,
      { orgId: tenant.org.id, recipientId: tenant.userIds.admin, unreadOnly: false, limit: 25, cursor: null },
    );
    expect(notificationsAfter.total).toBe(notificationsBefore.total);
    expect(rowCountFor(tenant.org.id)).toBe(0);
  });
});

