      orgId: other.org.id,
      name: "Epic",
      color: "#00ff00",
      description: null,
    });

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "labels-key-0001", [
        row("Labelled once", { labels: ["Bug", "bug", "Bug"] }),
        row("Labelled again", { labels: ["bug", "Epic"] }),
      ]),
    );

    const labels = await labelRepo.listLabels(tenant.org.id);
    const byName = new Map(labels.map((label) => [label.name, label]));
    expect(labels.map((label) => label.name).sort()).toEqual(["Bug", "Epic", "bug"]);
    expect(byName.get("bug")).toMatchObject({ color: "#94a3b8", description: null });
    expect(byName.get("Epic")?.id).not.toBe(
      (await labelRepo.listLabels(other.org.id)).find((label) => label.name === "Epic")?.id,
    );

    const [first, second] = result.issues;
    expect(first?.labelIds).toEqual([byName.get("Bug")?.id, byName.get("bug")?.id]);
    expect(second?.labelIds).toEqual([byName.get("bug")?.id, byName.get("Epic")?.id]);
  });
});

describe("services/issue-service — importIssues: downstream effects", () => {
  it("is searchable, counts on the usage meter, and is audited once", async () => {
    const tenant = await createTenant("imp-downstream", "growth");
    const usageBefore = (await usageRepo.getUsage(tenant.org.id)).issuesUsed;

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "downstream-key-01", [
        row("Lighthouse alpha"),
        row("Lighthouse beta"),
        row("Lighthouse gamma"),
      ]),
    );

    const hits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Lighthouse",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(hits.total).toBe(3);

    const usageAfter = (await usageRepo.getUsage(tenant.org.id)).issuesUsed;
    expect(usageAfter).toBe(usageBefore + 3);
    const recounted = await usageRepo.recomputeUsage(tenant.org.id);
    expect(recounted.issuesUsed).toBe(usageAfter);

    const audit = await activityService.listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      action: ["issues.imported"],
      limit: 25,
      cursor: null,
    });
