    expect(audit.items[0]).toMatchObject({
      action: "issues.imported",
      actorId: tenant.userIds.member,
      subjectKind: "project",
      subjectId: tenant.project.id,
      projectId: tenant.project.id,
      metadata: { count: 3, importKey: "downstream-key-01" },
    });
    expect(result.issues).toHaveLength(3);

    const perIssue = await activityService.listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      action: ["issue.created"],
      limit: 25,
      cursor: null,
    });
    expect(perIssue.total).toBe(0);
  });

  it("notifies nobody and queues no webhook delivery for the imported issues", async () => {
    const tenant = await createTenant("imp-quiet", "growth");
    await webhookService.createWebhook(tenant.actors.owner, {
      orgId: tenant.org.id,
      url: "https://hooks.example.test/taskflow",
      eventTypes: ["issue.created", "issue.status_changed"],
    });
    const notificationsBefore = await notificationService.listNotifications(
      tenant.actors.admin,
      { orgId: tenant.org.id, recipientId: tenant.userIds.admin, unreadOnly: false, limit: 25, cursor: null },
    );

    await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "quiet-key-000001", [row("Quiet row", { assigneeEmail: "admin@imp-quiet.test" })]),
    );

    const notificationsAfter = await notificationService.listNotifications(
      tenant.actors.admin,
      { orgId: tenant.org.id, recipientId: tenant.userIds.admin, unreadOnly: false, limit: 25, cursor: null },
    );
    expect(notificationsAfter.total).toBe(notificationsBefore.total);
    expect(rowCountFor(tenant.org.id)).toBe(0);
  });
});

