    await expect(issueRepo.countIssues(tenant.org.id, tenant.project.id)).resolves.toBe(0);

    const retry = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "rate-key-00001", [row("Retry row")]),
    );
    expect(retry.replayed).toBe(false);
  });

  it("sizes the allowance by the workspace's plan", async () => {
    const tenant = await createTenant("imp-rate-growth", "growth");
    const rows = Array.from({ length: 61 }, (_, index) => row(`Growth row ${index + 1}`));

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "growth-key-00001", rows),
    );
    expect(result.issues).toHaveLength(61);
  });
});

describe("services/issue-service — importIssues: replays", () => {
  it("returns the first result for a reused key, in the same order, and writes and publishes nothing", async () => {
    const tenant = await createTenant("imp-replay");
    const first = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "replay-key-0001", [row("Original A"), row("Original B")]),
    );

    const imported = capture("issues.imported");
    const created = capture("issue.created");
    const replay = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "replay-key-0001", [row("Changed C")]),
    );

    expect(replay.replayed).toBe(true);
    expect(replay.issues.map((issue) => issue.id)).toEqual(
      first.issues.map((issue) => issue.id),
    );
    expect(replay.issues.map((issue) => issue.title)).toEqual(["Original A", "Original B"]);
    expect(imported).toHaveLength(0);
    expect(created).toHaveLength(0);
    await expect(issueRepo.countIssues(tenant.org.id, tenant.project.id)).resolves.toBe(2);
  });

  it("treats the same rows under a different key as a new import", async () => {
    const tenant = await createTenant("imp-newkey");
    const rows = [row("Same rows")];

    const first = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "newkey-first-01", rows),
    );
    const second = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "newkey-second-1", rows),
    );

    expect(second.replayed).toBe(false);
    expect(second.issues[0]?.id).not.toBe(first.issues[0]?.id);
  });

  it("scopes keys to the workspace", async () => {
    const home = await createTenant("imp-keyhome");
    const away = await createTenant("imp-keyaway");

    await issueService.importIssues(
      home.actors.member,
      batch(home, "shared-key-0001", [row("Home row")]),
    );
    const sameKeyElsewhere = await issueService.importIssues(
      away.actors.member,
      batch(away, "shared-key-0001", [row("Away row")]),
    );

    expect(sameKeyElsewhere.replayed).toBe(false);
    expect(sameKeyElsewhere.issues[0]?.title).toBe("Away row");
  });
});

describe("services/issue-service — importIssues: assignees and labels", () => {
  it("matches assignees by email without case, and leaves anything else unassigned", async () => {
    const tenant = await createTenant("imp-assign");
    await userRepo.insertUser({
      email: "outsider@imp-assign.test",
      name: "Outsider",
      passwordHash: "seed",
    });
    const viewerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (viewerMember === null) throw new Error("viewer should be a member");
    await memberRepo.archiveMember(tenant.org.id, viewerMember.id);

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "assign-key-0001", [
        row("Case folded", { assigneeEmail: "ADMIN@imp-assign.test" }),
        row("Not a member", { assigneeEmail: "outsider@imp-assign.test" }),
        row("Removed member", { assigneeEmail: "viewer@imp-assign.test" }),
        row("Unknown address", { assigneeEmail: "nobody@imp-assign.test" }),
      ]),
    );

    expect(result.issues.map((issue) => issue.assigneeId)).toEqual([
      tenant.userIds.admin,
      null,
      null,
      null,
    ]);
  });

  it("matches labels exactly, creates each missing one once, and ignores other workspaces' labels", async () => {
    const tenant = await createTenant("imp-labels");
    const other = await createTenant("imp-labels-other");
    await labelRepo.insertLabel({
      orgId: tenant.org.id,
      name: "Bug",
      color: "#ff0000",
      description: null,
    });
    await labelRepo.insertLabel({
      orgId: other.org.id,
      name: "Epic",
      color: "#00ff00",
      description: null,
    });

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "labels-key-0001", [
        row("Labelled once", { labels: ["Bug", "bug", "Bug"] }),
        row("Labelled again", { labels: ["bug", "Epic"] }),
      ]),
    );

    const labels = await labelRepo.listLabels(tenant.org.id);
    const byName = new Map(labels.map((label) => [label.name, label]));
    expect(labels.map((label) => label.name).sort()).toEqual(["Bug", "Epic", "bug"]);
    expect(byName.get("bug")).toMatchObject({ color: "#94a3b8", description: null });
    expect(byName.get("Epic")?.id).not.toBe(
      (await labelRepo.listLabels(other.org.id)).find((label) => label.name === "Epic")?.id,
    );

    const [first, second] = result.issues;
    expect(first?.labelIds).toEqual([byName.get("Bug")?.id, byName.get("bug")?.id]);
    expect(second?.labelIds).toEqual([byName.get("bug")?.id, byName.get("Epic")?.id]);
  });
});

describe("services/issue-service — importIssues: downstream effects", () => {
  it("is searchable, counts on the usage meter, and is audited once", async () => {
    const tenant = await createTenant("imp-downstream", "growth");
    const usageBefore = (await usageRepo.getUsage(tenant.org.id)).issuesUsed;

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "downstream-key-01", [
        row("Lighthouse alpha"),
        row("Lighthouse beta"),
        row("Lighthouse gamma"),
      ]),
    );

    const hits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Lighthouse",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(hits.total).toBe(3);

    const usageAfter = (await usageRepo.getUsage(tenant.org.id)).issuesUsed;
    expect(usageAfter).toBe(usageBefore + 3);
    const recounted = await usageRepo.recomputeUsage(tenant.org.id);
    expect(recounted.issuesUsed).toBe(usageAfter);

    const audit = await activityService.listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      action: ["issues.imported"],
      limit: 25,
      cursor: null,
    });
    expect(audit.items).toHaveLength(1);
    expect(audit.items[0]).toMatchObject({
      action: "issues.imported",
      actorId: tenant.userIds.member,
      subjectKind: "project",
      subjectId: tenant.project.id,
      projectId: tenant.project.id,
      metadata: { count: 3, importKey: "downstream-key-01" },
    });
    expect(result.issues).toHaveLength(3);

    const perIssue = await activityService.listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      action: ["issue.created"],
      limit: 25,
      cursor: null,
    });
    expect(perIssue.total).toBe(0);
  });

  it("notifies nobody and queues no webhook delivery for the imported issues", async () => {
    const tenant = await createTenant("imp-quiet", "growth");
    await webhookService.createWebhook(tenant.actors.owner, {
      orgId: tenant.org.id,
      url: "https://hooks.example.test/taskflow",
      eventTypes: ["issue.created", "issue.status_changed"],
    });
    const notificationsBefore = await notificationService.listNotifications(
      tenant.actors.admin,
      { orgId: tenant.org.id, recipientId: tenant.userIds.admin, unreadOnly: false, limit: 25, cursor: null },
    );

    await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "quiet-key-000001", [row("Quiet row", { assigneeEmail: "admin@imp-quiet.test" })]),
    );

    const notificationsAfter = await notificationService.listNotifications(
      tenant.actors.admin,
      { orgId: tenant.org.id, recipientId: tenant.userIds.admin, unreadOnly: false, limit: 25, cursor: null },
    );
    expect(notificationsAfter.total).toBe(notificationsBefore.total);
    expect(rowCountFor(tenant.org.id)).toBe(0);
  });
});

